/* The band (band.h): a guitarist, a singer, a bassist and a drummer on the stage backdrop's deck, playing.
 *
 * The players are skinned characters generated by more-cartwheel-examples' brawler tools (MIT; models/band_*.glb, see
 * CREDITS), one bone layout: Hips, Spine, Chest, Neck, Head, UpperArm/LowerArm/Hand and UpperLeg/LowerLeg/Foot on each
 * side, their rest rotations identity, facing +Z with +X their left. Their play loops are made here, a pose a frame
 * from the beat: the strumming hand on the eighths, the bass plucked on the quarters, the drummer's sticks on the
 * beats and the backbeat, every head nodding with the song, swaying over the bar; a slow phrase over eight bars lifts
 * the singer's free arm and turns the guitarist toward the crowd. Every motion is a smooth curve of the beat (no
 * jumps), so a loop is a performance, not a flicker. The instruments are built from shapes here: a guitar and a
 * bass on straps (carried by the chest), a mic on its stand, a kit with cymbals, sticks in the drummer's hands. The
 * deck is in the haze of the stage's moving spots; the players sit either side of the middle, where the field's
 * rivers do not cover them. */
#include "band.h"

#include <math.h>
#include <stdio.h>
#include <string.h>

#include "cartwheel/core.h"
#include "cartwheel/resource.h"
#include "cartwheel/rim_light.h"
#include "cartwheel/scene.h"

#define PI 3.14159265f
enum { GUITAR, SINGER, BASS, DRUMS, PLAYERS };
static const char *const FILES[PLAYERS] = { "models/band_guitar.glb", "models/band_singer.glb", "models/band_bass.glb", "models/band_drums.glb" };
/* where each stands on the deck (its top is at 1.2), and which way it faces (a little toward the middle) */
static const float AT[PLAYERS][4] = { { -5.3f, 1.2f, -4.4f, 0.4f }, { -3.55f, 1.2f, -2.6f, 0.25f }, { 3.7f, 1.2f, -3.3f, -0.3f }, { 5.4f, 2.0f, -7.0f, -0.35f } };

#define AXE_AT ((t3_vec3){ -0.1f, -0.3f, 0.19f }) /* the instrument on its strap, in the chest frame */
#define AXE_ANGLE 0.5f
enum { B_HIPS, B_SPINE, B_CHEST, B_NECK, B_HEAD, B_UAL, B_LAL, B_HL, B_UAR, B_LAR, B_HR, B_ULL, B_LLL, B_FL, B_ULR, B_LLR, B_FR, BONES };
static const char *const BONE[BONES] = { "Hips", "Spine", "Chest", "Neck", "Head", "UpperArmL", "LowerArmL", "HandL", "UpperArmR", "LowerArmR",
                                         "HandR", "UpperLegL", "LowerLegL", "FootL", "UpperLegR", "LowerLegR", "FootR" };

static struct {
  bool built;
  cw_res res[PLAYERS];
  t3_object *bone[PLAYERS][BONES];
  t3_vec3 hips0[PLAYERS];
} N;

/* a pose: each bone's rotation offset from rest (x, y, z: q = qz * qy * qx, as the cast's own clips) */
typedef struct { float r[BONES][3]; float hips_dy; } pose;

static t3_quat euler(const float r[3]) {
  t3_quat qx = t3_quat_from_axis_angle((t3_vec3){ 1, 0, 0 }, r[0]), qy = t3_quat_from_axis_angle((t3_vec3){ 0, 1, 0 }, r[1]),
          qz = t3_quat_from_axis_angle((t3_vec3){ 0, 0, 1 }, r[2]);
  return t3_quat_multiply(t3_quat_multiply(qz, qy), qx);
}

/* materials: a matte plastic, a lacquered body, metal */
static t3_material *mat(float r, float g, float b, float rough, float metal, float coat) {
  t3_material *m = t3_mesh_physical_material_new(0xffffff);
  m->color = (t3_color){ r, g, b };
  m->roughness = rough, m->metalness = metal, m->clearcoat = coat, m->clearcoat_roughness = 0.1f;
  return m;
}
static t3_mesh *part(t3_object *at, t3_geometry *g, t3_material *m, t3_vec3 p, t3_quat q) {
  t3_mesh *o = t3_mesh_new(g, m);
  t3_release(g);
  T3_OBJ(o)->position = p, T3_OBJ(o)->quaternion = q;
  t3_object_add(at, o);
  t3_release(o);
  return o;
}
static t3_quat qa(float x, float y, float z, float a) { return t3_quat_from_axis_angle((t3_vec3){ x, y, z }, a); }

/* a guitar or a bass, its body at the origin, its neck along +x (long: the bass) */
static t3_object *axe(bool bass, t3_material *body_m, t3_material *dark, t3_material *metal) {
  t3_object *g = t3_group_new();
  float bl = bass ? 0.46f : 0.4f, neck = bass ? 0.95f : 0.68f;
  /* the body: two lobes in a slab */
  part(g, t3_cylinder_geometry_new(0.17f, 0.17f, 0.06f, 24, 1, false), body_m, (t3_vec3){ -0.06f, 0, 0 }, qa(1, 0, 0, PI / 2));
  part(g, t3_cylinder_geometry_new(0.13f, 0.13f, 0.06f, 24, 1, false), body_m, (t3_vec3){ 0.12f, 0.02f, 0 }, qa(1, 0, 0, PI / 2));
  part(g, t3_box_geometry_new(bl * 0.5f, 0.2f, 0.06f, 1, 1, 1), body_m, (t3_vec3){ 0.03f, 0, 0 }, qa(0, 0, 1, 0));
  /* the pickguard and the bridge */
  part(g, t3_box_geometry_new(0.08f, 0.1f, 0.01f, 1, 1, 1), dark, (t3_vec3){ -0.02f, -0.04f, 0.035f }, qa(0, 0, 1, 0));
  part(g, t3_box_geometry_new(0.03f, 0.08f, 0.015f, 1, 1, 1), metal, (t3_vec3){ -0.1f, 0, 0.035f }, qa(0, 0, 1, 0));
  /* the neck and the head */
  part(g, t3_box_geometry_new(neck, 0.05f, 0.03f, 1, 1, 1), dark, (t3_vec3){ 0.2f + neck * 0.5f, 0, 0.01f }, qa(0, 0, 1, 0));
  part(g, t3_box_geometry_new(0.14f, 0.07f, 0.025f, 1, 1, 1), dark, (t3_vec3){ 0.27f + neck, 0, 0.005f }, qa(0, 0, 1, 0.15f));
  return g;
}

static void build_kit(t3_object *at, t3_vec3 o) {
  t3_material *shell = mat(0.5f, 0.05f, 0.06f, 0.25f, 0.1f, 1), *head = mat(0.85f, 0.83f, 0.78f, 0.6f, 0, 0), *chrome = mat(0.8f, 0.8f, 0.82f, 0.2f, 1, 0),
              *brass = mat(0.75f, 0.55f, 0.2f, 0.25f, 1, 0);
  /* the kick drum on its side, facing out */
  part(at, t3_cylinder_geometry_new(0.36f, 0.36f, 0.4f, 28, 1, false), shell, (t3_vec3){ o.x, o.y + 0.36f, o.z + 0.55f }, qa(1, 0, 0, PI / 2));
  part(at, t3_cylinder_geometry_new(0.33f, 0.33f, 0.01f, 28, 1, false), head, (t3_vec3){ o.x, o.y + 0.36f, o.z + 0.76f }, qa(1, 0, 0, PI / 2));
  /* the snare, the toms, the floor tom */
  part(at, t3_cylinder_geometry_new(0.2f, 0.2f, 0.14f, 24, 1, false), shell, (t3_vec3){ o.x + 0.32f, o.y + 0.65f, o.z + 0.35f }, qa(1, 0, 0, 0.2f));
  part(at, t3_cylinder_geometry_new(0.16f, 0.16f, 0.2f, 24, 1, false), shell, (t3_vec3){ o.x - 0.15f, o.y + 0.85f, o.z + 0.45f }, qa(1, 0, 0, 0.4f));
  part(at, t3_cylinder_geometry_new(0.16f, 0.16f, 0.2f, 24, 1, false), shell, (t3_vec3){ o.x + 0.18f, o.y + 0.85f, o.z + 0.48f }, qa(1, 0, 0, 0.4f));
  part(at, t3_cylinder_geometry_new(0.22f, 0.22f, 0.4f, 24, 1, false), shell, (t3_vec3){ o.x - 0.45f, o.y + 0.42f, o.z + 0.25f }, qa(0, 0, 1, 0));
  /* cymbals on chrome stands: a ride, a crash, the hi-hat */
  static const float CY[3][4] = { { -0.75f, 1.35f, 0.35f, 0.28f }, { 0.6f, 1.45f, 0.45f, 0.24f }, { 0.65f, 1.0f, 0.15f, 0.17f } };
  for (int i = 0; i < 3; i++) {
    t3_vec3 p = { o.x + CY[i][0], o.y + CY[i][1], o.z + CY[i][2] };
    part(at, t3_cylinder_geometry_new(CY[i][3], CY[i][3] * 0.2f, 0.02f, 32, 1, false), brass, p, qa(1, 0, 0, 0.25f));
    part(at, t3_cylinder_geometry_new(0.012f, 0.012f, CY[i][1], 8, 1, false), chrome, (t3_vec3){ p.x, o.y + CY[i][1] * 0.5f, p.z }, qa(0, 0, 1, 0));
  }
  t3_release(shell), t3_release(head), t3_release(chrome), t3_release(brass);
}

void band_build(cw_node stage_root) {
  if (N.built) return;
  N.built = true;
  t3_material *red = mat(0.55f, 0.04f, 0.03f, 0.18f, 0.05f, 1), *sunburst = mat(0.6f, 0.35f, 0.1f, 0.2f, 0.05f, 1), *dark = mat(0.03f, 0.025f, 0.02f, 0.55f, 0, 0),
              *metal = mat(0.8f, 0.8f, 0.82f, 0.25f, 1, 0), *black = mat(0.02f, 0.02f, 0.02f, 0.4f, 0.2f, 0.5f);
  for (int p = 0; p < PLAYERS; p++) {
    N.res[p] = cw_res_load(FILES[p], CW_RES_GLTF);
    if (!cw_res_gltf(N.res[p])) { cw_error("band: %s did not load", FILES[p]); continue; }
    char nm[16];
    snprintf(nm, sizeof nm, "Player%d", p);
    cw_node n = cw_node_new("Node3D", nm);
    cw_node_add_child(stage_root, n);
    cw_node3d_set_position(n, (t3_vec3){ AT[p][0], AT[p][1], AT[p][2] });
    cw_node3d_set_rotation(n, (t3_vec3){ 0, AT[p][3], 0 });
    t3_object *o = cw_gltf_instantiate(N.res[p]);
    cw_node3d_set_object(n, o);
    /* a rim of the back light round each player, cold on the left of the stage and warm on the right as the back
     * lights are, so each reads as a figure against the dark wall (each player's own materials: its own glTF) */
    {
      cw_rim_light_desc rd = cw_rim_light_default();
      rd.color = p == GUITAR || p == SINGER ? (t3_color){ 0.45f, 0.65f, 1.0f } : (t3_color){ 1.0f, 0.45f, 0.6f };
      rd.strength = 1.3f, rd.power = 2.8f, rd.near = 0, rd.far = 1, rd.close = 1;
      cw_rim_light_apply_tree(o, &rd);
    }
    t3_release(o);
    for (int b = 0; b < BONES; b++) N.bone[p][b] = t3_object_get_by_name(o, BONE[b]);
    if (N.bone[p][B_HIPS]) N.hips0[p] = N.bone[p][B_HIPS]->position;
    t3_object *chest = N.bone[p][B_CHEST];
    if ((p == GUITAR || p == BASS) && chest) {
      /* slung on its strap: the body at the right hip, the neck up across to the left hand */
      t3_object *a = axe(p == BASS, p == BASS ? sunburst : red, dark, metal);
      a->position = AXE_AT;
      a->quaternion = qa(0, 0, 1, AXE_ANGLE);
      t3_object_add(chest, a);
      t3_release(a);
    }
    if (p == DRUMS) {
      for (int s = 0; s < 2; s++) { /* the sticks, along each hand */
        t3_object *h = N.bone[p][s ? B_HR : B_HL];
        if (!h) continue;
        part(h, t3_cylinder_geometry_new(0.012f, 0.008f, 0.42f, 6, 1, false), sunburst, (t3_vec3){ 0, -0.08f, 0.16f }, qa(1, 0, 0, PI / 2 - 0.3f));
      }
      build_kit(cw_node3d_object(n), (t3_vec3){ 0, 0, 0.25f });
    }
    if (p == SINGER) { /* the mic on its stand in front of the singer */
      t3_object *at = cw_node3d_object(n);
      part(at, t3_cylinder_geometry_new(0.015f, 0.015f, 1.45f, 8, 1, false), metal, (t3_vec3){ 0, 0.72f, 0.42f }, qa(1, 0, 0, -0.08f));
      part(at, t3_cylinder_geometry_new(0.16f, 0.16f, 0.03f, 16, 1, false), black, (t3_vec3){ 0, 0.015f, 0.46f }, qa(1, 0, 0, 0));
      part(at, t3_sphere_geometry_new(0.045f, 12, 8), metal, (t3_vec3){ 0, 1.5f, 0.33f }, qa(1, 0, 0, 0));
      part(at, t3_cylinder_geometry_new(0.025f, 0.02f, 0.14f, 10, 1, false), black, (t3_vec3){ 0, 1.47f, 0.37f }, qa(1, 0, 0, -0.9f));
    }
  }
  /* amps behind the guitar and the bass: black boxes with a grille */
  for (int s = -1; s <= 1; s += 2) {
    t3_object *at = cw_node3d_object(stage_root);
    part(at, t3_box_geometry_new(1.1f, 1.3f, 0.6f, 1, 1, 1), black, (t3_vec3){ (float)s * 4.5f, 1.2f + 0.65f, -6.6f }, qa(0, 1, 0, -(float)s * 0.2f));
    part(at, t3_box_geometry_new(0.95f, 1.0f, 0.02f, 1, 1, 1), dark, (t3_vec3){ (float)s * 4.5f - (float)s * 0.06f, 1.2f + 0.6f, -6.29f }, qa(0, 1, 0, -(float)s * 0.2f));
  }
  t3_release(red), t3_release(sunburst), t3_release(dark), t3_release(metal), t3_release(black);
}

/* 0..1 smooth pulses on the beat: an ease out from each beat (a hit), never a step */
static float hit(float ph) { float f = ph - floorf(ph); return expf(-f * 7.0f) * fminf(1, f * 30.0f); }
static float wave(float ph) { return 0.5f + 0.5f * sinf(2 * PI * ph); }

static void pose_player(int p, float beat, float energy, pose *o) {
  memset(o, 0, sizeof *o);
  float nod = hit(beat) * (0.6f + 0.4f * energy), bar = sinf(2 * PI * beat / 4), phrase = wave(beat / 32);
  float (*r)[3] = o->r;
  /* the whole body moves: the hips sway over the bar and shift the weight from foot to foot over two, the louder the
   * song the deeper the nod (a head-bang in a drop, still a smooth curve of the beat) */
  float shift = sinf(PI * beat / 4);
  if (p != DRUMS) {
    r[B_HIPS][1] = 0.12f * bar, r[B_HIPS][2] = 0.05f * shift;
    r[B_ULL][0] += -0.06f * fmaxf(0, shift), r[B_LLL][0] += 0.12f * fmaxf(0, shift);
    r[B_ULR][0] += -0.06f * fmaxf(0, -shift), r[B_LLR][0] += 0.12f * fmaxf(0, -shift);
  }
  nod *= 0.7f + 0.6f * energy;
  switch (p) {
  case GUITAR: {
    float strum = sinf(2 * PI * beat * 2) * 0.5f; /* down and up on the eighths */
    r[B_SPINE][0] = 0.12f + 0.06f * nod, r[B_SPINE][1] = 0.15f * bar;
    r[B_CHEST][1] = -0.25f + 0.2f * phrase;
    r[B_HEAD][0] = 0.1f + 0.28f * nod;
    r[B_UAL][0] = -0.75f, r[B_UAL][2] = 0.35f, r[B_LAL][0] = -1.55f, r[B_LAL][1] = 0.4f; /* the fretting hand up the neck */
    r[B_UAR][0] = -0.35f + 0.12f * strum, r[B_UAR][2] = -0.25f, r[B_LAR][0] = -1.15f + 0.35f * strum;
    r[B_ULL][2] = 0.18f, r[B_ULR][2] = -0.18f, r[B_ULL][0] = -0.1f * nod, r[B_LLL][0] = 0.2f * nod, r[B_ULR][0] = -0.1f * nod, r[B_LLR][0] = 0.2f * nod;
    o->hips_dy = -0.04f * nod;
    break;
  }
  case BASS: {
    float pluck = hit(beat) - 0.5f;
    r[B_SPINE][0] = 0.08f + 0.04f * nod, r[B_SPINE][1] = -0.12f * bar;
    r[B_HEAD][0] = 0.05f + 0.25f * nod, r[B_HEAD][1] = -0.2f;
    r[B_UAL][0] = -0.65f, r[B_UAL][2] = 0.3f, r[B_LAL][0] = -1.45f, r[B_LAL][1] = 0.4f;
    r[B_UAR][0] = -0.4f, r[B_UAR][2] = -0.2f, r[B_LAR][0] = -1.1f + 0.25f * pluck;
    r[B_ULL][2] = 0.12f, r[B_ULR][2] = -0.12f, r[B_ULL][0] = -0.1f * nod, r[B_LLL][0] = 0.2f * nod, r[B_ULR][0] = -0.1f * nod, r[B_LLR][0] = 0.2f * nod;
    o->hips_dy = -0.04f * nod;
    break;
  }
  case SINGER: {
    float lift = phrase; /* the free arm rises with the phrase */
    r[B_SPINE][0] = 0.05f + 0.05f * nod, r[B_SPINE][2] = 0.06f * bar;
    r[B_HEAD][0] = -0.05f + 0.18f * nod, r[B_HEAD][1] = 0.08f * bar;
    r[B_UAR][0] = -1.15f, r[B_UAR][2] = -0.15f, r[B_LAR][0] = -1.65f; /* holding the mic */
    /* raised out to the side toward the crowd, clear of the face */
    r[B_UAL][0] = -0.25f - 0.75f * lift, r[B_UAL][2] = 0.3f + 1.35f * lift, r[B_LAL][0] = -0.25f - 0.45f * (1 - lift);
    r[B_ULL][2] = 0.1f, r[B_ULR][2] = -0.1f, r[B_LLL][0] = 0.15f * nod, r[B_LLR][0] = 0.15f * nod;
    o->hips_dy = -0.03f * nod;
    break;
  }
  case DRUMS: {
    /* sitting at the kit: the right stick on the eighths (the hats), the left on the backbeat (2 and 4) */
    float rh = hit(beat * 2), lh = hit((beat + 1) / 2) ;
    r[B_ULL][0] = -1.45f, r[B_LLL][0] = 1.5f, r[B_ULR][0] = -1.45f, r[B_LLR][0] = 1.5f, r[B_ULL][2] = 0.2f, r[B_ULR][2] = -0.2f;
    r[B_SPINE][0] = 0.15f + 0.05f * nod;
    r[B_HEAD][0] = 0.15f + 0.3f * nod;
    r[B_UAR][0] = -0.55f - 0.25f * (1 - rh), r[B_UAR][2] = -0.3f, r[B_LAR][0] = -1.0f - 0.5f * (1 - rh);
    r[B_UAL][0] = -0.5f - 0.3f * (1 - lh), r[B_UAL][2] = 0.3f, r[B_LAL][0] = -0.9f - 0.6f * (1 - lh);
    r[B_HR][0] = 0.3f * rh, r[B_HL][0] = 0.3f * lh;
    o->hips_dy = -0.42f;
    break;
  }
  }
}

/* ── the hands: two-bone reach (upper arm, lower arm) solved in the chest's frame, so a hand is on the neck, at the
 * strings, on the mic or over a drum whatever the body does ── */
static t3_quat qconj(t3_quat q) { return (t3_quat){ -q.x, -q.y, -q.z, q.w }; }
static float dot3(t3_vec3 a, t3_vec3 b) { return a.x * b.x + a.y * b.y + a.z * b.z; }
static t3_quat from_to(t3_vec3 a, t3_vec3 b) { /* the shortest rotation from unit a to unit b */
  t3_vec3 c = t3_vec3_cross(a, b);
  float w = 1 + dot3(a, b);
  if (w < 1e-5f) return t3_quat_from_axis_angle(fabsf(a.x) < 0.9f ? (t3_vec3){ 1, 0, 0 } : (t3_vec3){ 0, 0, 1 }, PI);
  t3_quat q = { c.x, c.y, c.z, w };
  float n = sqrtf(q.x * q.x + q.y * q.y + q.z * q.z + q.w * q.w);
  return (t3_quat){ q.x / n, q.y / n, q.z / n, q.w / n };
}
/* the arm of side s (0 left, 1 right) of player p reaches for T (in the chest's frame), its elbow toward pole P */
static void reach(int p, int s, t3_vec3 T, t3_vec3 P) {
  t3_object *ua = N.bone[p][s ? B_UAR : B_UAL], *la = N.bone[p][s ? B_LAR : B_LAL], *hd = N.bone[p][s ? B_HR : B_HL];
  if (!ua || !la || !hd) return;
  t3_vec3 S = ua->position;
  float l1 = sqrtf(dot3(la->position, la->position)), l2 = sqrtf(dot3(hd->position, hd->position));
  t3_vec3 d = t3_vec3_sub(T, S);
  float len = sqrtf(dot3(d, d)), dl = fminf(fmaxf(len, fabsf(l1 - l2) + 1e-3f), (l1 + l2) * 0.999f);
  t3_vec3 dn = t3_vec3_scale(d, 1 / fmaxf(len, 1e-6f));
  /* the elbow: along the reach by a, out toward the pole by h */
  float a = (l1 * l1 - l2 * l2 + dl * dl) / (2 * dl), h = sqrtf(fmaxf(0, l1 * l1 - a * a));
  t3_vec3 pp = t3_vec3_sub(P, S);
  t3_vec3 side = t3_vec3_sub(pp, t3_vec3_scale(dn, dot3(pp, dn)));
  float sl = sqrtf(dot3(side, side));
  side = sl > 1e-6f ? t3_vec3_scale(side, 1 / sl) : (t3_vec3){ 0, -1, 0 };
  t3_vec3 E = t3_vec3_add(t3_vec3_scale(dn, a), t3_vec3_scale(side, h)); /* from S */
  t3_vec3 H = t3_vec3_scale(dn, dl);
  /* the upper arm's -y along S to E; the lower arm's -y (in the upper arm's frame) along E to H */
  t3_vec3 down = { 0, -1, 0 };
  t3_quat qu = from_to(down, t3_vec3_normalize(E));
  /* a twist about the upper arm so its frame's own bend axis lies across the bend: keeps the elbow from rolling */
  ua->quaternion = qu;
  t3_vec3 fl = t3_vec3_apply_quat(t3_vec3_normalize(t3_vec3_sub(H, E)), qconj(qu));
  la->quaternion = from_to(down, fl);
}
/* the chest's frame in the model's: from the hips, spine and chest of the pose (their rest translations, the pose's
 * rotations) */
static void chest_frame(int p, const pose *o, t3_vec3 *pos, t3_quat *rot) {
  t3_object *h = N.bone[p][B_HIPS], *sp = N.bone[p][B_SPINE], *ch = N.bone[p][B_CHEST];
  t3_vec3 P = { N.hips0[p].x, N.hips0[p].y + o->hips_dy, N.hips0[p].z };
  t3_quat Q = euler(o->r[B_HIPS]);
  P = t3_vec3_add(P, t3_vec3_apply_quat(sp->position, Q)), Q = t3_quat_multiply(Q, euler(o->r[B_SPINE]));
  P = t3_vec3_add(P, t3_vec3_apply_quat(ch->position, Q)), Q = t3_quat_multiply(Q, euler(o->r[B_CHEST]));
  (void)h;
  *pos = P, *rot = Q;
}
static t3_vec3 to_chest(t3_vec3 m, t3_vec3 cp, t3_quat cq) { return t3_vec3_apply_quat(t3_vec3_sub(m, cp), qconj(cq)); }

void band_update(float beat, float t, float energy) {
  (void)t;
  if (!N.built) return;
  for (int p = 0; p < PLAYERS; p++) {
    if (!N.bone[p][B_HIPS]) continue;
    pose o;
    pose_player(p, beat + 0.07f * (float)p, energy, &o); /* each a hair off the others: a band, not a machine */
    for (int b = 0; b < BONES; b++)
      if (N.bone[p][b]) N.bone[p][b]->quaternion = euler(o.r[b]);
    N.bone[p][B_HIPS]->position = (t3_vec3){ N.hips0[p].x, N.hips0[p].y + o.hips_dy, N.hips0[p].z };
    if (!N.bone[p][B_CHEST] || !N.bone[p][B_SPINE]) continue;
    float bt = beat + 0.07f * (float)p;
    t3_vec3 cp;
    t3_quat cq;
    chest_frame(p, &o, &cp, &cq);
    if (p == GUITAR || p == BASS) {
      /* the instrument's frame in the chest's: its strap holds it there (band_build) */
      t3_vec3 ap = AXE_AT;
      float ang = AXE_ANGLE, ca = cosf(ang), sa = sinf(ang);
      bool bass = p == BASS;
      /* the fretting hand on the neck, sliding up and down it over the phrase; the picking hand at the strings */
      float fret = (bass ? 0.55f : 0.42f) + 0.12f * sinf(2 * PI * bt / 16);
      float pick = bass ? 0.04f * (hit(bt) - 0.5f) : 0.07f * sinf(2 * PI * bt * 2);
      t3_vec3 Tl = { ap.x + fret * ca, ap.y + fret * sa - 0.04f, ap.z + 0.06f };
      t3_vec3 Tr = { ap.x - 0.02f - pick * sa, ap.y + pick * ca + 0.02f, ap.z + 0.08f };
      reach(p, 0, Tl, (t3_vec3){ 0.5f, -0.3f, -0.2f });
      reach(p, 1, Tr, (t3_vec3){ -0.5f, 0.0f, -0.3f });
    } else if (p == SINGER) {
      t3_vec3 mic = { 0, 1.38f, 0.36f }; /* the mic on its stand, in the model's frame */
      reach(p, 1, to_chest(mic, cp, cq), to_chest((t3_vec3){ -0.5f, 0.9f, 0.0f }, cp, cq));
    } else if (p == DRUMS) {
      /* the right stick on the eighths over the floor tom and ride side, the left on the backbeat over the snare */
      float rh = hit(bt * 2), lh = hit((bt + 1) / 2);
      t3_vec3 Tr = { -0.32f, 1.0f + 0.22f * (1 - rh), 0.42f }, Tl = { 0.28f, 0.95f + 0.28f * (1 - lh), 0.5f };
      reach(p, 1, to_chest(Tr, cp, cq), to_chest((t3_vec3){ -0.7f, 0.6f, 0.0f }, cp, cq));
      reach(p, 0, to_chest(Tl, cp, cq), to_chest((t3_vec3){ 0.7f, 0.6f, 0.0f }, cp, cq));
    }
  }
}
